-- API 1.1. Separate schema preserves the historical BD.sql tables.
CREATE SCHEMA IF NOT EXISTS jasna;
SET search_path TO jasna, public;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, role text NOT NULL CHECK(role IN ('master','parent')), full_name text NOT NULL, login text UNIQUE, password_hash text, email text, phone text);
CREATE TABLE families (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, parent_user_id uuid NOT NULL UNIQUE REFERENCES users(id));
CREATE TABLE children (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, family_id uuid NOT NULL REFERENCES families(id), full_name text NOT NULL CHECK(length(full_name)>0), birth_date date, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE access_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, family_id uuid NOT NULL REFERENCES families(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, user_id uuid NOT NULL REFERENCES users(id), family_id uuid REFERENCES families(id), access_link_id uuid REFERENCES access_links(id), role text NOT NULL CHECK(role IN ('master','parent')), token_hash text NOT NULL UNIQUE, csrf_token text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE TABLE groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, master_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, capacity integer NOT NULL CHECK(capacity>0), is_individual boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, description text, CHECK(NOT is_individual OR capacity=1));
CREATE TABLE lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, group_id uuid NOT NULL REFERENCES groups(id), master_id uuid NOT NULL REFERENCES users(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, capacity integer NOT NULL CHECK(capacity>0), status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','completed','cancelled')), cancel_reason text, notes text, CHECK(ends_at>starts_at));
CREATE TABLE attendance_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, group_id uuid REFERENCES groups(id), valid_from date NOT NULL, valid_to date, attended_charge_lesson boolean NOT NULL, missed_charge_lesson boolean NOT NULL, parent_cancel_charge_lesson boolean NOT NULL, free_cancel_before_hours integer NOT NULL CHECK(free_cancel_before_hours>=0), parent_cancel_allowed boolean NOT NULL, cancel_deadline_hours integer NOT NULL CHECK(cancel_deadline_hours>=0), transfer_allowed boolean NOT NULL, transfer_deadline_hours integer NOT NULL CHECK(transfer_deadline_hours>=0), transfer_charge_lesson boolean NOT NULL, single_lesson_price_minor bigint NOT NULL CHECK(single_lesson_price_minor>0), ending_notice_days integer NOT NULL CHECK(ending_notice_days>=0), ending_notice_lessons integer NOT NULL CHECK(ending_notice_lessons>=0), CHECK(valid_to IS NULL OR valid_to>=valid_from));
CREATE TABLE plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, group_id uuid NOT NULL REFERENCES groups(id), title text NOT NULL, lessons_total integer NOT NULL CHECK(lessons_total>0), validity_days integer NOT NULL CHECK(validity_days>0), price_minor bigint NOT NULL CHECK(price_minor>0), currency text NOT NULL DEFAULT 'RUB' CHECK(currency='RUB'), is_active boolean NOT NULL DEFAULT true);
CREATE TABLE bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, lesson_id uuid NOT NULL REFERENCES lessons(id), child_id uuid NOT NULL REFERENCES children(id), family_id uuid NOT NULL REFERENCES families(id), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','cancelled_by_parent','cancelled_by_master')), cancelled_at timestamptz, cancelled_by uuid REFERENCES users(id), rule_snapshot jsonb NOT NULL, rule_id uuid NOT NULL REFERENCES attendance_rules(id));
CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, family_id uuid NOT NULL REFERENCES families(id), child_id uuid NOT NULL REFERENCES children(id), group_id uuid NOT NULL REFERENCES groups(id), kind text NOT NULL CHECK(kind IN ('subscription','single_lesson')), booking_id uuid REFERENCES bookings(id), plan_snapshot jsonb, amount_minor bigint NOT NULL CHECK(amount_minor>0), currency text NOT NULL DEFAULT 'RUB' CHECK(currency='RUB'), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','paid','cancelled')), compensated boolean NOT NULL DEFAULT false, valid_from date, valid_until date, CHECK(kind<>'subscription' OR (valid_from IS NOT NULL AND valid_until>=valid_from)));
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, invoice_id uuid NOT NULL REFERENCES invoices(id), family_id uuid NOT NULL REFERENCES families(id), child_id uuid NOT NULL REFERENCES children(id), amount_minor bigint NOT NULL CHECK(amount_minor>0), currency text NOT NULL DEFAULT 'RUB' CHECK(currency='RUB'), method text NOT NULL CHECK(method IN ('cash','transfer','online','sbp')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','succeeded','canceled')), provider_payment_id text UNIQUE, provider_key text UNIQUE, payment_url text, paid_at timestamptz, comment text);
CREATE TABLE subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, invoice_id uuid NOT NULL UNIQUE REFERENCES invoices(id), child_id uuid NOT NULL REFERENCES children(id), family_id uuid NOT NULL REFERENCES families(id), group_id uuid NOT NULL REFERENCES groups(id), lessons_total integer NOT NULL CHECK(lessons_total>0), lessons_remaining integer NOT NULL DEFAULT 0 CHECK(lessons_remaining>=0), valid_from date NOT NULL, valid_until date NOT NULL CHECK(valid_until>=valid_from));
CREATE TABLE attendance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, booking_id uuid NOT NULL UNIQUE REFERENCES bookings(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','attended','missed','cancelled')), cancel_reason text CHECK(cancel_reason IN ('parent','master','transfer')), charged boolean NOT NULL DEFAULT false, subscription_id uuid REFERENCES subscriptions(id), invoice_id uuid REFERENCES invoices(id), charge_entry_id uuid, marked_at timestamptz, marked_by uuid REFERENCES users(id), comment text);
CREATE TABLE subscription_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, subscription_id uuid NOT NULL REFERENCES subscriptions(id), delta integer NOT NULL CHECK(delta<>0), reason text NOT NULL CHECK(reason IN ('subscription_purchase','attendance_charge','attendance_reversal','manual_adjustment')), attendance_id uuid REFERENCES attendance(id), payment_id uuid REFERENCES payments(id), reverses_entry_id uuid UNIQUE REFERENCES subscription_ledger(id), created_by uuid REFERENCES users(id), comment text);
CREATE TABLE money_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, family_id uuid NOT NULL REFERENCES families(id), invoice_id uuid NOT NULL REFERENCES invoices(id), payment_id uuid REFERENCES payments(id), amount_minor bigint NOT NULL CHECK(amount_minor<>0), reason text NOT NULL, source_id uuid NOT NULL, reverses_entry_id uuid UNIQUE REFERENCES money_ledger(id));
CREATE TABLE receipts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, payment_id uuid NOT NULL UNIQUE REFERENCES payments(id), kind text NOT NULL CHECK(kind IN ('file','link')), external_link text, mime_type text, file_name text, content bytea, uploaded_by uuid NOT NULL REFERENCES users(id), uploaded_at timestamptz NOT NULL DEFAULT now(), CHECK((kind='file' AND content IS NOT NULL AND external_link IS NULL AND octet_length(content)<=10485760) OR (kind='link' AND content IS NULL AND external_link IS NOT NULL)));
CREATE TABLE receipt_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, receipt_id uuid NOT NULL REFERENCES receipts(id), snapshot jsonb NOT NULL, content bytea, comment text NOT NULL, actor_id uuid NOT NULL REFERENCES users(id));
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, user_id uuid NOT NULL REFERENCES users(id), family_id uuid REFERENCES families(id), type text NOT NULL, payload jsonb NOT NULL, event_key text NOT NULL UNIQUE, read_at timestamptz);
CREATE TABLE outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, user_id uuid NOT NULL REFERENCES users(id), family_id uuid REFERENCES families(id), type text NOT NULL, payload jsonb NOT NULL, event_key text NOT NULL UNIQUE, delivered_at timestamptz);
CREATE TABLE audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, event_type text NOT NULL, actor_user_id uuid REFERENCES users(id), actor_role text NOT NULL, resource_type text NOT NULL, resource_id uuid, before_state jsonb, after_state jsonb, reason text, request_id text);
CREATE TABLE idempotency (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, user_id uuid NOT NULL REFERENCES users(id), route text NOT NULL, key text NOT NULL, body_hash text NOT NULL, status_code integer NOT NULL, response jsonb NOT NULL, UNIQUE(user_id,route,key));

CREATE UNIQUE INDEX bookings_active ON bookings(lesson_id,child_id) WHERE status='active';
CREATE UNIQUE INDEX invoices_booking ON invoices(booking_id) WHERE booking_id IS NOT NULL;
CREATE UNIQUE INDEX payments_pending ON payments(invoice_id) WHERE status='pending';
CREATE UNIQUE INDEX subscription_purchase ON subscription_ledger(subscription_id) WHERE reason='subscription_purchase';
CREATE UNIQUE INDEX payment_credit ON money_ledger(payment_id) WHERE reason='payment';
CREATE INDEX children_family ON children(family_id);
CREATE INDEX bookings_family ON bookings(family_id);
CREATE INDEX bookings_lesson ON bookings(lesson_id,status);
CREATE INDEX lessons_time ON lessons(starts_at,ends_at);
CREATE INDEX subscriptions_child ON subscriptions(child_id,valid_until);
CREATE INDEX payments_family ON payments(family_id,created_at);
CREATE INDEX money_family ON money_ledger(family_id,invoice_id);
CREATE INDEX notifications_user ON notifications(user_id,read_at);
CREATE INDEX audit_resource ON audit_log(resource_type,resource_id,created_at);
CREATE INDEX sessions_link ON sessions(access_link_id);
CREATE FUNCTION update_subscription_balance() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 UPDATE subscriptions SET lessons_remaining=lessons_remaining+NEW.delta,version=version+1 WHERE id=NEW.subscription_id;
 RETURN NEW;
END $$;
CREATE TRIGGER ledger_balance AFTER INSERT ON subscription_ledger FOR EACH ROW EXECUTE FUNCTION update_subscription_balance();
CREATE FUNCTION immutable_history() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'history is immutable'; END $$;
CREATE TRIGGER immutable_subscription BEFORE UPDATE OR DELETE ON subscription_ledger FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER immutable_money BEFORE UPDATE OR DELETE ON money_ledger FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_log FOR EACH ROW EXECUTE FUNCTION immutable_history();
